fn getdomain(x: Vec<i8>) -> Vec<i8> {
    // Since the input vector is guaranteed non-empty, we can
    // initialize our min and max with the first element.
    let mut min_val = x[0];
    let mut max_val = x[0];

    // Iterate over the rest to update min and max.
    for &v in &x[1..] {
        if v < min_val {
            min_val = v;
        }
        if v > max_val {
            max_val = v;
        }
    }

    // Return a two-element vector [min, max].
    vec![min_val, max_val]
}

